const hempPestsMissouri = source({
  title: 'Insect Pests of Industrial Hemp in Missouri',
  organization: 'University of Missouri Extension',
  url: 'https://extension.missouri.edu/publications/mx83',
  authors: ['Anjeeta Nain', 'Kelly A. Nelson', 'Gurbir Singh', 'Peng Tian', 'Emily Althoff', 'Ivair Valmorbida', 'Gurpreet Kaur'],
  publisher: 'University of Missouri Extension',
  publicationDate: '2025-10-01',
  year: 2025,
  accessedDate: '2026-08-20',
  supportedClaims: [
    'Spotted cucumber beetle adults feed on hemp foliage and floral tissue, producing holes and ragged edges, while larvae can feed on root hairs and root tips.',
    'The Missouri Extension guide lists chlorotic spots, curling, terminal stunting, distorted buds, and bud abortion as possible tarnished plant bug injury on hemp; these institutional symptom claims conflict with earlier hemp literature that had not documented foliar symptoms and therefore require organism-linked human review.',
    'Dectes texanus larvae can bore inside hemp stems and pith, producing internal galleries, wilting, dieback, swollen or split stems, and increased breakage risk.',
    'Cabbage looper larvae feed on hemp leaves, often from lower-leaf undersides upward, producing large irregular holes and potentially damaging floral buds.',
    'Japanese beetle adults feed on hemp foliage and can skeletonize leaves between veins; adults are metallic green with bronze wing covers and often aggregate.',
    'Armyworm larvae can create irregular holes and skeletonization and may enter hemp buds or flowers, where silk and frass can accompany feeding injury.',
    'Hemp insect pressure varies by region, growth stage, and variety, so damage morphology without organism evidence should not be treated as species confirmation.',
  ],
})

const hempPestSystems2019 = source({
  title: 'Developing Insect Pest Management Systems for Hemp in the United States: A Work in Progress',
  organization: 'Journal of Integrated Pest Management (Cranshaw et al.)',
  url: 'https://doi.org/10.1093/jipm/pmz023',
  authors: ['Whitney Cranshaw', 'Melissa Schreiner', 'Kadie Britt', 'Thomas P. Kuhar', 'John McPartland', 'Jerome Grant'],
  publisher: 'Oxford University Press for the Entomological Society of America',
  publicationDate: '2019-08-28',
  year: 2019,
  accessedDate: '2026-08-20',
  doi: '10.1093/jipm/pmz023',
  supportedClaims: [
    'Lygus species were among the insects most commonly encountered on hemp, at least tarnished plant bug and pale legume bug bred on the crop, and Lygus lineolaris occurred from emergence to harvest in Virginia observations.',
    'The 2019 hemp synthesis reported that no visible leaf injury by Lygus species had yet been observed, while seed-feeding injury potential remained unclear.',
    'Lygus numbers could be higher after flowering, but flower-bud abscission, seed abortion, and seed deformity were effects known from other crops and hemp data were then absent to establish significance for seed production or quality.',
    'Japanese beetle was observed on hemp east of the Mississippi as a highly visible, potentially significant defoliator that also feeds readily on hemp flowers; Figure 4 documents an adult on hemp.',
    'Across the broader hemp defoliator complex, serious defoliation had only rarely been observed and experiments were still needed to connect defoliation with seed, fiber, cannabinoid, and biomass outcomes.',
    'The 2019 profile was an early synthesis based mainly on Colorado, Virginia, and Tennessee observations through the end of 2018, so it does not establish a universal hemp action threshold or cultivar response.',
  ],
})

